import{_ as o,l as r,o as e,c as s,v as t,p as l,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"指数成分历史","description":"","frontmatter":{"title":"指数成分历史","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/index-constituents-history.md","filePath":"quant/index-constituents-history.md","lastUpdated":1789023840000}'),h={name:"quant/index-constituents-history.md"};function E(u,a,m,_,f,A){const n=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="指数成分历史" tabindex="-1">指数成分历史 <a class="header-anchor" href="#指数成分历史" aria-label="Permalink to &quot;指数成分历史&quot;">​</a></h1><div class="epigraph"><p>指数是一条时变的可投资名单。用今天的成分表回填十年，存活下来的公司会看起来永远可买，调入调出那天的冲击却从样本里消失。</p><footer>—— Shumway, The Delisting Bias in CRSP Data, Journal of Finance, 1997；对照 S&amp;P Dow Jones、MSCI、中证指数的公开编制方案；指数基金与 ETF 调仓的实证传统</footer></div><p><a href="/quant/analyst-consensus">上一课</a>把信息集停在分析师。<a href="/quant/crsp-compustat">CRSP</a>已处理退市。本课的缺口是<strong>基准与宇宙的历史名单</strong>：谁在指数里、何时调入调出、公告日与生效日之差。用当前沪深 300 或 S&amp;P 500 成员做二十年回测，是经典存活偏差。后课复权处理价格尺度；本课处理集合的成员关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因子研究的宇宙常写「指数成分」。指数编制有规则：市值、流动性、上市时间、财务、缓冲区。成分在定期调整日与临时替换日变化。供应商给的「历史成分」若只提供最新规则下的回算，而不是当时官方名单，则 2005 年的组合可能含当时尚未上市或尚未入选的公司。问题是区分三种表：（1）当时官方点-in-time 成分；（2）今日规则对历史的回测指数；（3）当前成员的历史价格。只有（1）能模拟当时可交易的指数策略；（2）是指数公司的研究产品；（3）非法。</p><p>调仓有公告日与生效日。公告后、生效前，被动资金必须交易，冲击与提前调仓是公开的市场微观结构现象。用生效日收盘价「自动调入」且零冲击，会高估指数增强与套利的可实现性。ETF 一级市场与期货展期把同一事件放大到多个场所。</p><h3 id="缓冲区与快速入选改变换手" tabindex="-1">缓冲区与快速入选改变换手 <a class="header-anchor" href="#缓冲区与快速入选改变换手" aria-label="Permalink to &quot;缓冲区与快速入选改变换手&quot;">​</a></h3><p>编制方案里的缓冲区降低换手，使「刚过线」不一定入选。快速入选规则让新上市公司提前进入。回测若用简单市值排序模拟成分，换手与名单都会错，跟踪误差归因会把编制规则当成 alpha。必须订阅官方历史或高质量点-in-time 成分库，并保存方案版本。</p><p><span class="marginnote">中证、上证、深证指数的编制方案与调整日历是公开的。A 股还要叠 ST、退市整理、注册制新股。用今天的 300 成分跑 2013 年，会纳入当时不存在的科创板代码。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主数据：<code>(index_id, date, member_id, start, end, announce_ts, effective_ts, weight)</code>。权重方法（流通市值、自由流通、分级靠档）按当时方案。回测决策日 \\(t\\) 只用 <code>announce_ts ≤ t</code> 且 <code>effective_ts</code> 规则明确的信息：若策略不能提前调仓，则生效日前仍用旧名单。冲击：在生效窗口对调入调出腿施加参与率约束，见<a href="/quant/capacity-participation">容量</a>。</p><p>与 CRSP/A 股主数据对齐时检查：调出是否因并购或退市，收益是否已按退市处理。指数本身的收益应用官方指数水平验证，与成分加权复制之间的差来自费用、停牌、现金拖累与编制细节。差过大说明成分或权重错。</p><h3 id="基准是产品-不是自然物" tabindex="-1">基准是产品，不是自然物 <a class="header-anchor" href="#基准是产品-不是自然物" aria-label="Permalink to &quot;基准是产品，不是自然物&quot;">​</a></h3><p>同一「价值因子」相对不同指数，行业与市值暴露不同。论文必须锁定基准历史，而不是锁定基准名字。指数增强的跟踪误差定义在特定指数的点-in-time 成分与权重上；换指数等于换问题。后课中国公募指增会用到本课对象。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>存活偏差：当前成员是条件于存活与入选的样本，历史收益偏高、左尾被砍。调仓冲击：被动需求在窗口内缺乏弹性，价格暂时偏离，然后部分回复——这是实施缺口，也可能是可交易的拥挤。两者都要求历史名单，而不是当前名单。</p><p>自由流通与外资持股限制改变权重，从而改变「市场组合」代理。用总市值权重去复制自由流通指数，beta 会错。方案文本是数据契约的一部分。</p>',17)),(e(),l(p,null,{default:i(()=>[c(n,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Ann%5B%22%E8%B0%83%E6%95%B4%E5%85%AC%E5%91%8A%22%5D%20--%3E%20PIT%5B%22%E7%82%B9-in-time%20%E5%90%8D%E5%8D%95%22%5D%0A%20%20PIT%20--%3E%20Eff%5B%22%E7%94%9F%E6%95%88%E6%97%A5%20%E8%A2%AB%E5%8A%A8%E4%BA%A4%E6%98%93%22%5D%0A%20%20Eff%20--%3E%20Impact%5B%22%E8%B0%83%E5%85%A5%E8%B0%83%E5%87%BA%E5%86%B2%E5%87%BB%22%5D%0A%20%20Today%5B%22%E5%BD%93%E5%89%8D%E6%88%90%E5%91%98%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20Bias%5B%22%E5%AD%98%E6%B4%BB%E5%81%8F%E5%B7%AE%22%5D%0A%20%20Rules%5B%22%E7%BC%96%E5%88%B6%E6%96%B9%E6%A1%88%E7%89%88%E6%9C%AC%22%5D%20--%3E%20PIT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指数公司对历史数据有许可。本课不提供未授权的成分库。自定义宇宙（全 A、可融券子集）须另存，不要冒充官方指数。债券指数、商品指数的滚动规则不同，本课以股票指数为主。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>只用当时官方成分与权重；当前成员回填是存活偏差。</li><li>公告日与生效日分开；调仓窗口有冲击，不能零成本换仓。</li><li>基准锁定的是历史方案，不是指数商品名。</li><li>出处：Shumway, <em>JF</em>, 1997；各指数公司公开编制方案。</li></ul>',4))])}const T=o(h,[["render",E]]);export{q as __pageData,T as default};
